class Solution {public:string solve(string text){vector<string> prefixes;vector<int> counts;string current;int number=0;bool pending=false;for(char c:text){if(c>='0'&&c<='9'){if(!pending&&c=='0')return "INVALID";number=number*10+(c-'0');pending=true;if(number>10000)return "INVALID";}else if(c=='['){if(!pending||number<1)return "INVALID";prefixes.push_back(current);counts.push_back(number);current="";number=0;pending=false;}else if(c==']'){if(pending||counts.empty())return "INVALID";int count=counts.back();counts.pop_back();string prefix=prefixes.back();prefixes.pop_back();if(prefix.size()+1LL*current.size()*count>10000)return "INVALID";string repeated;for(int i=0;i<count;i++)repeated+=current;current=prefix+repeated;}else if(c>='a'&&c<='z'){if(pending)return "INVALID";current+=c;if(current.size()>10000)return "INVALID";}else return "INVALID";}return pending||!counts.empty()?"INVALID":current;}};